ullets": ["Built developer productivity monitor collecting webhook telemetry across 50+ repositories.", "Designed intuitive telemetry charts for tracking deployment frequency and lead time."]}]', '["Python", "FastAPI", "JavaScript", "React", "TypeScript", "PostgreSQL", "Docker", "Git", "REST APIs", "Tailwind CSS"]', '[{"name": "AWS Certified Cloud Practitioner", "issuer": "Amazon Web Services", "date": "2024"}, {"name": "Meta Front-End Developer Professional Certificate", "issuer": "Coursera", "date": "2023"}]', FALSE, '6fc89cca302a47d4a1e8b0d905a49f4c', '2026-10-11 09:33:29.762433', '2026-10-11 09:41:11.659067') ON CONFLICT (id) DO NOTHING;
