-- Table: jobs
CREATE TABLE IF NOT EXISTS jobs (
    id VARCHAR(36) PRIMARY KEY,
    title VARCHAR(150) NOT NULL,
    company_name VARCHAR(100) NOT NULL,
    company_logo_url VARCHAR(500),
    company_website VARCHAR(255),
    domain VARCHAR(50) NOT NULL,
    job_type VARCHAR(50) NOT NULL,
    work_mode VARCHAR(50) NOT NULL,
    location VARCHAR(100) NOT NULL,
    stipend_or_salary VARCHAR(100),
    experience_level VARCHAR(50) NOT NULL,
    skills_required TEXT NOT NULL,
    description TEXT NOT NULL,
    responsibilities TEXT,
    requirements TEXT,
    apply_url VARCHAR(500),
    application_method VARCHAR(20) NOT NULL DEFAULT 'INTERNAL',
    application_url VARCHAR(500),
    recruiter_email VARCHAR(255),
    application_instructions TEXT,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    is_featured BOOLEAN NOT NULL DEFAULT FALSE,
    application_start_date TIMESTAMP WITHOUT TIME ZONE,
    deadline TIMESTAMP WITHOUT TIME ZONE,
    eligible_batches TEXT,
    candidate_type TEXT,
    eligible_qualifications TEXT,
    experience_requirements TEXT,
    created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);

INSERT INTO jobs (title, company_name, company_logo_url, company_website, domain, job_type, work_mode, location, stipend_or_salary, experience_level, skills_required, description, responsibilities, requirements, apply_url, application_method, application_url, recruiter_email, application_instructions, is_active, is_featured, application_start_date, deadline, eligible_batches, candidate_type, eligible_qualifications, experience_requirements, id, created_at, updated_at) VALUES ('Frontend Software Engineer Intern', 'Vercel', 'https://assets.vercel.com/image/upload/v1588863393/front/favicon/vercel/180x180.png', 'https://vercel.com', 'Frontend', 'Internship', 'Remote', 'Remote (US / Canada)', '$45/hr (~$7,200/mo)', 'Internship', '["React", "TypeScript", "Next.js", "Tailwind CSS"]', 'Join Vercel''s design systems and web framework team building the future of the Frontend Cloud. You will work closely with staff engineers optimizing component performance and developer experience.', '["Develop accessible, responsive UI primitives for Next.js starter templates.", "Collaborate with senior designers and engineers to implement micro-interactions.", "Write unit and end-to-end component tests using Vitest and Playwright."]', '["Currently enrolled in or recent graduate of a Computer Science or related degree.", "Hands-on proficiency with React, TypeScript, and modern CSS frameworks.", "Demonstrated personal portfolio projects or open-source contributions."]', 'https://vercel.com/careers', 'INTERNAL', NULL, NULL, NULL, TRUE, TRUE, NULL, NULL, '["All Batches"]', '["All Candidates"]', '["Any Qualification"]', NULL, 'efe9fdbe27d244c5b38bbc518a361b5c', '2026-10-11 09:07:56.693669', '2026-10-11 09:07:56.693677') ON CONFLICT (id) DO NOTHING;
INSERT INTO jobs (title, company_name, company_logo_url, company_website, domain, job_type, work_mode, location, stipend_or_salary, experience_level, skills_required, description, responsibilities, requirements, apply_url, application_method, application_url, recruiter_email, application_instructions, is_active, is_featured, application_start_date, deadline, eligible_batches, candidate_type, eligible_qualifications, experience_requirements, id, created_at, updated_at) VALUES ('Junior Backend Developer', 'Stripe', 'https://images.ctfassets.net/f60q1anpxzid/fidelity-hero/f2ea1c322b72f1cefb52199f7d4e51ec/stripe-logo.png', 'https://stripe.com', 'Backend', 'Full-time', 'Hybrid', 'Seattle, WA / San Francisco, CA', '$115,000 - $135,000/yr', 'Entry Level', '["Python", "FastAPI", "PostgreSQL", "Docker", "Redis"]', 'Stripe is expanding its payments infrastructure team. As an entry-level backend engineer, you will write robust APIs that power millions of financial transactions per minute worldwide.', '["Design and build resilient, high-throughput RESTful and RPC microservices.", "Manage relational database schemas, migrations, and query indexing.", "Participate in design reviews and incident post-mortems."]', '["Strong computer science fundamentals (data structures, algorithms, concurrency).", "Proficiency in Python, Go, or Java with database query optimization experience.", "Strong communication and collaborative problem-solving skills."]', 'https://stripe.com/jobs', 'INTERNAL', NULL, NULL, NULL, TRUE, TRUE, NULL, NULL, '["All Batches"]', '["All Candidates"]', '["Any Qualification"]', NULL, 'cc038a344fb847d5b397770f8473b3c2', '2026-10-11 09:07:56.693695', '2026-10-11 09:07:56.693698') ON CONFLICT (id) DO NOTHING;
INSERT INTO jobs (title, company_name, company_logo_url, company_website, domain, job_type, work_mode, location, stipend_or_salary, experience_level, skills_required, description, responsibilities, requirements, apply_url, application_method, application_url, recruiter_email, application_instructions, is_active, is_featured, application_start_date, deadline, eligible_batches, candidate_type, eligible_qualifications, experience_requirements, id, created_at, updated_at) VALUES ('AI Research & ML Engineering Intern', 'Scale AI', 'https://scale.com/favicon.ico', 'https://scale.com', 'AI / Machine Learning', 'Internship', 'Onsite', 'San Francisco, CA', '$8,000/mo ($50/hr)', 'Internship', '["PyTorch", "Python", "Transformers", "NLP", "LLMs"]', 'Work directly with leading AI researchers benchmarking frontier foundation models, fine-tuning task-specific LLMs, and developing evaluation harness suites.', '["Train and evaluate transformer checkpoints using PyTorch and Hugging Face.", "Curate synthetic data generation pipelines for multi-modal evaluation.", "Document benchmark results and present insights to engineering leads."]', '["Experience training neural networks in PyTorch or JAX.", "Familiarity with RLHF, LoRA, and LLM fine-tuning techniques.", "Strong Python scripting and Linux environment fluency."]', 'https://scale.com/careers', 'INTERNAL', NULL, NULL, NULL, TRUE, TRUE, NULL, NULL, '["All Batches"]', '["All Candidates"]', '["Any Qualification"]', NULL, 'c1ea0c10ea8347b6ba415bcf44925cfd', '2026-10-11 09:07:56.693710', '2026-10-11 09:07:56.693712') ON CONFLICT (id) DO NOTHING;
INSERT INTO jobs (title, company_name, company_logo_url, company_website, domain, job_type, work_mode, location, stipend_or_salary, experience_level, skills_required, description, responsibilities, requirements, apply_url, application_method, application_url, recruiter_email, application_instructions, is_active, is_featured, application_start_date, deadline, eligible_batches, candidate_type, eligible_qualifications, experience_requirements, id, created_at, updated_at) VALUES ('Full-Stack Software Engineer (New Grad)', 'Datadog', 'https://img.datadoghq.com/img/favicon.ico', 'https://datadoghq.com', 'Full-Stack Development', 'Full-time', 'Remote', 'Remote (Global)', '$120,000 - $140,000/yr', 'Entry Level', '["React", "Go", "TypeScript", "PostgreSQL", "Kubernetes"]', 'Datadog''s Observability Platform team is seeking junior engineers passionate about building real-time telemetry dashboards and scalable telemetry ingestion endpoints.', '["Implement interactive dashboard widgets visualizing live telemetry metrics.", "Maintain backend services handling high-frequency time-series data.", "Collaborate with UX designers to refine data visualization workflows."]', '["Bachelor''s degree in CS, Software Engineering, or equivalent practical experience.", "Knowledge of web protocols, asynchronous programming, and REST APIs.", "Experience building full-stack web applications with React."]', 'https://datadoghq.com/careers', 'INTERNAL', NULL, NULL, NULL, TRUE, FALSE, NULL, NULL, '["All Batches"]', '["All Candidates"]', '["Any Qualification"]', NULL, '8a6e48533829456e9cf7d7b61a4e9c8c', '2026-10-11 09:07:56.693724', '2026-10-11 09:07:56.693726') ON CONFLICT (id) DO NOTHING;
INSERT INTO jobs (title, company_name, company_logo_url, company_website, domain, job_type, work_mode, location, stipend_or_salary, experience_level, skills_required, description, responsibilities, requirements, apply_url, application_method, application_url, recruiter_email, application_instructions, is_active, is_featured, application_start_date, deadline, eligible_batches, candidate_type, eligible_qualifications, experience_requirements, id, created_at, updated_at) VALUES ('Cloud Infrastructure & DevOps Intern', 'Cloudflare', 'https://www.cloudflare.com/favicon.ico', 'https://cloudflare.com', 'Cloud & DevOps', 'Internship', 'Remote', 'Remote (Americas & EMEA)', '$40/hr (~$6,400/mo)', 'Internship', '["Terraform", "Docker", "AWS", "Linux", "CI/CD"]', 'Help secure and accelerate the internet. Our Infrastructure Engineering team invites interns to contribute directly to edge edge routing, automated deployment pipelines, and zero-downtime infrastructure.', '["Automate CI/CD pipelines using GitHub Actions and container registries.", "Write infrastructure-as-code definitions with Terraform.", "Monitor edge cluster health and diagnostic alerts."]', '["Knowledge of Linux system administration and containerization (Docker).", "Basic understanding of TCP/IP, DNS, and TLS handshakes.", "Curiosity about distributed systems and edge networking."]', 'https://cloudflare.com/careers', 'INTERNAL', NULL, NULL, NULL, TRUE, FALSE, NULL, NULL, '["All Batches"]', '["All Candidates"]', '["Any Qualification"]', NULL, 'd1324e9b37884121b4b521ee13b17265', '2026-10-11 09:07:56.693738', '2026-10-11 09:07:56.693739') ON CONFLICT (id) DO NOTHING;
INSERT INTO jobs (title, company_name, company_logo_url, company_website, domain, job_type, work_mode, location, stipend_or_salary, experience_level, skills_required, description, responsibilities, requirements, apply_url, application_method, application_url, recruiter_email, application_instructions, is_active, is_featured, application_start_date, deadline, eligible_batches, candidate_type, eligible_qualifications, experience_requirements, id, created_at, updated_at) VALUES ('Junior Mobile Engineer (React Native)', 'Airbnb', 'https://a0.muscache.com/airbnb/static/icons/apple-touch-icon-180x180.png', 'https://airbnb.com', 'Mobile Development', 'Full-time', 'Hybrid', 'San Francisco, CA', '$110,000 - $130,000/yr', 'Entry Level', '["React Native", "TypeScript", "iOS", "Android", "GraphQL"]', 'Join Airbnb''s Guest Experience mobile engineering guild. You will craft fluid, accessible mobile screens that empower millions of travelers around the world.', '["Build native and cross-platform UI views adhering to design guidelines.", "Integrate GraphQL client queries with Apollo and offline cache management.", "Debug cross-device performance and animation framerate drops."]', '["Hands-on experience developing mobile applications using React Native.", "Solid foundation in JavaScript/TypeScript and asynchronous event handling.", "Portfolio of mobile project applications or app store releases."]', 'https://airbnb.com/careers', 'INTERNAL', NULL, NULL, NULL, TRUE, FALSE, NULL, NULL, '["All Batches"]', '["All Candidates"]', '["Any Qualification"]', NULL, '3eaedb78c898477681c437994737604a', '2026-10-11 09:07:56.693749', '2026-10-11 09:07:56.693751') ON CONFLICT (id) DO NOTHING;


-- Table: job_applications
CREATE TABLE IF NOT EXISTS job_applications (
    id VARCHAR(36) PRIMARY KEY,
    user_id VARCHAR(36) NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    job_id VARCHAR(36) NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,
    company_name VARCHAR(100) NOT NULL,
    position_title VARCHAR(150) NOT NULL,
    job_location VARCHAR(100),
    work_mode VARCHAR(50),
    salary_or_stipend VARCHAR(100),
    job_url VARCHAR(500),
    status VARCHAR(50) NOT NULL DEFAULT 'Applied',
    applied_date TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    next_interview_date TIMESTAMP WITHOUT TIME ZONE,
    notes TEXT,
    created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);

INSERT INTO job_applications (user_id, job_id, company_name, position_title, job_location, work_mode, salary_or_stipend, job_url, status, applied_date, next_interview_date, notes, id, created_at, updated_at) VALUES ('a47f8c3881724dd1a23795de9b726274', 'c1ea0c10ea8347b6ba415bcf44925cfd', 'Scale AI', 'AI Research & ML Engineering Intern', 'San Francisco, CA', 'Onsite', '$8,000/mo ($50/hr)', 'https://scale.com/careers', 'Applied', '2026-10-11 09:34:35.449462', NULL, NULL, '48a207871244434bad9d4badfaea6b21', '2026-10-11 09:34:35.470319', '2026-10-11 09:34:35.470335') ON CONFLICT (id) DO NOTHING;


-- Table: projects
CREATE TABLE IF NOT EXISTS projects (
    id VARCHAR(36) PRIMARY KEY,
    owner_id VARCHAR(36) NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    title VARCHAR(150) NOT NULL,
    slug VARCHAR(150) UNIQUE NOT NULL,
    short_description VARCHAR(300) NOT NULL,
    problem_statement TEXT NOT NULL,
    objectives TEXT NOT NULL,
    features TEXT NOT NULL,
    tech_stack TEXT NOT NULL,
    prerequisites TEXT,
    difficulty VARCHAR(20) NOT NULL DEFAULT 'Intermediate',
    estimated_duration VARCHAR(50) NOT NULL,
    expected_outcome TEXT NOT NULL,
    cover_image_url VARCHAR(500),
    screenshots TEXT,
    contributors TEXT,
    zip_storage_key VARCHAR(255),
    zip_file_size_bytes INTEGER DEFAULT 0,
    github_url VARCHAR(255) NOT NULL,
    live_demo_url VARCHAR(255),
    video_demo_url VARCHAR(255),
    domain VARCHAR(50) NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'Draft',
    published_at TIMESTAMP WITHOUT TIME ZONE,
    reviewer_notes TEXT,
    views_count INTEGER NOT NULL DEFAULT 0,
    stars_count INTEGER NOT NULL DEFAULT 0,
    bookmarks_count INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);

INSERT INTO projects (owner_id, title, slug, short_description, problem_statement, objectives, features, tech_stack, prerequisites, difficulty, estimated_duration, expected_outcome, cover_image_url, screenshots, contributors, zip_storage_key, zip_file_size_bytes, github_url, live_demo_url, video_demo_url, domain, status, published_at, reviewer_notes, views_count, stars_count, bookmarks_count, id, created_at, updated_at) VALUES ('a47f8c3881724dd1a23795de9b726274', 'AI Resume Matcher & ATS Scorer', 'ai-resume-matcher', 'NLP pipeline comparing student resumes with job specs, calculating ATS alignment and actionable skill gap recommendations.', 'Students struggle to understand why their resumes are filtered out by automated applicant tracking systems (ATS). This platform uses NLP and semantic vector embeddings to analyze match scores and recommend exact keyword enhancements.', 'Implement PDF text parsing, vectorize resume content, compute cosine similarity against job descriptions, and deliver interactive recommendations.', '["ATS compatibility score (0-100%)", "Missing skills and keyword gap report", "Interactive PDF resume parser", "Gemini AI suggestion rewrite engine"]', '["FastAPI", "React", "Gemini AI", "PostgreSQL", "Python"]', 'Basic Python, knowledge of REST APIs, basic React fundamentals.', 'Intermediate', '2-3 weeks', 'A deployed web app where students can upload any resume and job description to get instant ATS scoring.', NULL, '[{"image_url": "https://images.unsplash.com/photo-1586281380349-632531db7ed4?auto=format&fit=crop&w=1200&q=80", "caption": "Live ATS parsing and semantic match score breakdown", "order_index": 0}, {"image_url": "https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&w=1200&q=80", "caption": "Actionable skill gap matrix and missing keyword detections", "order_index": 1}, {"image_url": "https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&w=1200&q=80", "caption": "Gemini AI interactive resume bullet enhancement editor", "order_index": 2}]', '[]', NULL, 0, 'https://github.com/alexstudent/ai-resume-matcher', 'https://ats-matcher-demo.dev', NULL, 'AI / Machine Learning', 'Published', '2026-10-11 09:07:56.656639', NULL, 346, 89, 42, 'ad96b20a2270401fa52ced19201846c9', '2026-10-11 09:07:56.656687', '2026-10-11 09:36:22.736279') ON CONFLICT (id) DO NOTHING;
INSERT INTO projects (owner_id, title, slug, short_description, problem_statement, objectives, features, tech_stack, prerequisites, difficulty, estimated_duration, expected_outcome, cover_image_url, screenshots, contributors, zip_storage_key, zip_file_size_bytes, github_url, live_demo_url, video_demo_url, domain, status, published_at, reviewer_notes, views_count, stars_count, bookmarks_count, id, created_at, updated_at) VALUES ('a47f8c3881724dd1a23795de9b726274', 'Multi-Cloud Kubernetes Cost Optimizer', 'cloud-cost-optimizer', 'Automated controller collecting node telemetry and pod utilization to cut idle Kubernetes cluster spend by up to 40%.', 'Startups and cloud teams overprovision Kubernetes worker nodes by default, generating thousands of dollars in wasted monthly cloud compute spend.', 'Develop custom metrics CRD, Horizontal Pod Autoscaling integrations, and cost visualization dashboards.', '["Custom metrics CRD", "Horizontal Pod Autoscaling integration", "Prometheus metrics exporter", "Grafana cost forecasting dashboard"]', '["Go", "Kubernetes", "AWS", "Prometheus", "Docker"]', 'Go syntax, Docker containerization, Kubernetes basic architecture.', 'Advanced', '3-4 weeks', 'A lightweight cluster agent running in-cluster that delivers real-time right-sizing suggestions.', NULL, '[]', '[]', NULL, 0, 'https://github.com/alexstudent/k8s-cost-optimizer', NULL, NULL, 'Cloud & DevOps', 'Published', '2026-10-11 09:07:56.667348', NULL, 215, 64, 31, 'ef6fd8fd85fb453e9c7934701a17f299', '2026-10-11 09:07:56.667413', '2026-10-11 09:07:56.667421') ON CONFLICT (id) DO NOTHING;
INSERT INTO projects (owner_id, title, slug, short_description, problem_statement, objectives, features, tech_stack, prerequisites, difficulty, estimated_duration, expected_outcome, cover_image_url, screenshots, contributors, zip_storage_key, zip_file_size_bytes, github_url, live_demo_url, video_demo_url, domain, status, published_at, reviewer_notes, views_count, stars_count, bookmarks_count, id, created_at, updated_at) VALUES ('a47f8c3881724dd1a23795de9b726274', 'CampusBite — University Food Delivery App', 'campus-bite-delivery', 'Hyper-local ordering app connecting campus dining halls and student dorms with real-time driver tracking and peer couriers.', 'Commercial delivery apps charge high delivery and service fees that college students cannot afford, while dining halls experience huge lunch rushes.', 'Create a cross-platform mobile app allowing students to order from campus spots and pick up or peer-deliver.', '["Real-time order geolocation tracker", "Campus dining hall menu sync", "Student wallet & discount codes", "Push notification alert system"]', '["React Native", "Expo", "FastAPI", "PostgreSQL", "Tailwind CSS"]', 'JavaScript / TypeScript, React Native basics, REST API integration.', 'Intermediate', '2-3 weeks', 'A smooth mobile application running in iOS simulator and Android emulator.', NULL, '[]', '[]', NULL, 0, 'https://github.com/alexstudent/campus-bite-app', NULL, NULL, 'Mobile Development', 'Published', '2026-10-11 09:07:56.667427', NULL, 198, 52, 28, 'a10c2680548841a5a48e84b8b5e762c9', '2026-10-11 09:07:56.667442', '2026-10-11 09:07:56.667444') ON CONFLICT (id) DO NOTHING;
INSERT INTO projects (owner_id, title, slug, short_description, problem_statement, objectives, features, tech_stack, prerequisites, difficulty, estimated_duration, expected_outcome, cover_image_url, screenshots, contributors, zip_storage_key, zip_file_size_bytes, github_url, live_demo_url, video_demo_url, domain, status, published_at, reviewer_notes, views_count, stars_count, bookmarks_count, id, created_at, updated_at) VALUES ('a47f8c3881724dd1a23795de9b726274', 'DevLink — Student Developer Showcase & Network', 'devlink-portfolio-hub', 'Modern web application enabling engineering students to showcase verified projects, GitHub repositories, and interactive demos to tech recruiters.', 'Students often have scattered repositories and PDF resumes without an engaging, verified public URL to share with hiring managers.', 'Build an authenticated profile builder with interactive skills tagging and public portfolio slugs.', '["Public profile slug (/u/:username)", "GitHub OAuth integration", "Project showcase cards", "Recruiter direct contact form"]', '["React", "Tailwind CSS", "FastAPI", "PostgreSQL", "Docker"]', 'HTML, CSS, React hooks, FastAPI basics.', 'Beginner', '1-2 weeks', 'A responsive full-stack platform with authentication and public portfolio views.', NULL, '[]', '[]', NULL, 0, 'https://github.com/alexstudent/devlink-platform', 'https://devlink-showcase.dev', NULL, 'Web Development', 'Published', '2026-10-11 09:07:56.667450', NULL, 512, 110, 67, '5c7feadd86eb4ce49de241b4377373fa', '2026-10-11 09:07:56.667461', '2026-10-11 09:07:56.667463') ON CONFLICT (id) DO NOTHING;
INSERT INTO projects (owner_id, title, slug, short_description, problem_statement, objectives, features, tech_stack, prerequisites, difficulty, estimated_duration, expected_outcome, cover_image_url, screenshots, contributors, zip_storage_key, zip_file_size_bytes, github_url, live_demo_url, video_demo_url, domain, status, published_at, reviewer_notes, views_count, stars_count, bookmarks_count, id, created_at, updated_at) VALUES ('a47f8c3881724dd1a23795de9b726274', 'Real-Time Collaborative Code Editor', 'realtime-collaborative-editor', 'Browser-based multiplayer code IDE with synchronized cursor markers, syntax highlighting, and live in-memory execution.', 'Pair programming remotely often requires clunky screen-sharing rather than seamless concurrent coding in the same file.', 'Implement WebSockets with Conflict-free Replicated Data Types (CRDTs) to synchronize keystrokes across multiple connected clients.', '["CRDT concurrent conflict resolution", "Live presence indicators and multiple cursors", "Monaco code editor embedding", "Dockerized code execution sandbox"]', '["TypeScript", "React", "WebSocket", "Node.js", "Redis"]', 'Async JavaScript, WebSocket protocols, state synchronization concepts.', 'Advanced', '3-4 weeks', 'A multiplayer web IDE supporting real-time simultaneous edits with low latency.', NULL, '[]', '[]', NULL, 0, 'https://github.com/alexstudent/collab-code-editor', NULL, NULL, 'Web Development', 'Published', '2026-10-11 09:07:56.667468', NULL, 430, 95, 54, '0c4d8c3fc610442c825674e393d0886e', '2026-10-11 09:07:56.667482', '2026-10-11 09:07:56.667484') ON CONFLICT (id) DO NOTHING;
INSERT INTO projects (owner_id, title, slug, short_description, problem_statement, objectives, features, tech_stack, prerequisites, difficulty, estimated_duration, expected_outcome, cover_image_url, screenshots, contributors, zip_storage_key, zip_file_size_bytes, github_url, live_demo_url, video_demo_url, domain, status, published_at, reviewer_notes, views_count, stars_count, bookmarks_count, id, created_at, updated_at) VALUES ('a47f8c3881724dd1a23795de9b726274', 'FinTrack — Student Budget & Expense Analytics', 'fintrack-personal-finance', 'Visual budget planner designed for college students to track loans, rent, recurring subscriptions, and campus dining budgets.', 'College students frequently lose track of small recurring subscriptions and struggle with monthly budgeting under tight allowances.', 'Provide clean interactive visualizations, monthly budgeting envelopes, and CSV import capabilities.', '["Categorized monthly expense breakdown", "Recurring subscription detector", "Export to CSV and PDF reports", "Predictive end-of-semester balance forecast"]', '["React", "Chart.js", "Python", "SQLite", "Tailwind CSS"]', 'Basic React, component state management, data visualization libraries.', 'Beginner', '1-2 weeks', 'A clean personal finance dashboard with interactive chart breakdowns.', NULL, '[]', '[]', NULL, 0, 'https://github.com/alexstudent/fintrack-student', NULL, NULL, 'Web Development', 'Published', '2026-10-11 09:07:56.667489', NULL, 175, 38, 19, 'e331db7db9a54d1396d4a8a3b3e34c84', '2026-10-11 09:07:56.667500', '2026-10-11 09:07:56.667502') ON CONFLICT (id) DO NOTHING;
INSERT INTO projects (owner_id, title, slug, short_description, problem_statement, objectives, features, tech_stack, prerequisites, difficulty, estimated_duration, expected_outcome, cover_image_url, screenshots, contributors, zip_storage_key, zip_file_size_bytes, github_url, live_demo_url, video_demo_url, domain, status, published_at, reviewer_notes, views_count, stars_count, bookmarks_count, id, created_at, updated_at) VALUES ('a47f8c3881724dd1a23795de9b726274', 'Deep Learning Chest X-Ray Diagnosis Assistant', 'medical-pneumonia-detector', 'Convolutional neural network diagnostic tool classifying chest X-rays to detect pneumonia with Grad-CAM visual heatmaps.', 'Radiologists in remote clinics face heavy backlogs; AI diagnostic triage can assist by highlighting suspicious pulmonary regions.', 'Train a CNN on public NIH chest X-ray datasets, calculate Grad-CAM saliency maps, and expose a clean web inference endpoint.', '["96.2% validation accuracy ResNet-50 backbone", "Grad-CAM explainability heatmap overlay", "DICOM and PNG image upload parser", "Clinical findings summary generator"]', '["Python", "PyTorch", "OpenCV", "FastAPI", "React"]', 'Deep learning fundamentals, PyTorch tensor manipulation, CNN architectures.', 'Advanced', '3-4 weeks', 'An end-to-end model and web interface generating diagnostic probabilities and visual heatmap overlays.', NULL, '[]', '[]', NULL, 0, 'https://github.com/alexstudent/chest-xray-ai', NULL, NULL, 'AI / Machine Learning', 'Published', '2026-10-11 09:07:56.667508', NULL, 382, 88, 49, '92829c9ec773462a95627c7f1f283784', '2026-10-11 09:07:56.667518', '2026-10-11 09:14:11.380090') ON CONFLICT (id) DO NOTHING;
INSERT INTO projects (owner_id, title, slug, short_description, problem_statement, objectives, features, tech_stack, prerequisites, difficulty, estimated_duration, expected_outcome, cover_image_url, screenshots, contributors, zip_storage_key, zip_file_size_bytes, github_url, live_demo_url, video_demo_url, domain, status, published_at, reviewer_notes, views_count, stars_count, bookmarks_count, id, created_at, updated_at) VALUES ('a47f8c3881724dd1a23795de9b726274', 'Real-Time Stock Market Streaming Data Pipeline', 'stock-market-streaming-pipeline', 'High-throughput streaming ETL pipeline ingesting live market ticker websockets, processing windowed aggregations, and persisting to analytical lakehouse.', 'Financial algorithmic analysis requires millisecond streaming ingestion and rolling volume-weighted average price (VWAP) computations.', 'Set up Kafka topics, PySpark streaming processors, and DuckDB analytical storage.', '["Sub-second ticker ingestion", "1-minute and 5-minute rolling VWAP calculations", "Outlier trade anomaly detection", "Real-time websocket broadcast to client dashboard"]', '["Apache Kafka", "Python", "PySpark", "DuckDB", "FastAPI"]', 'Distributed systems basics, Python streaming generators, SQL query design.', 'Intermediate', '2-3 weeks', 'A running streaming pipeline with real-time console metrics and data persistence.', NULL, '[]', '[]', NULL, 0, 'https://github.com/alexstudent/kafka-market-pipeline', NULL, NULL, 'Data Engineering', 'Published', '2026-10-11 09:07:56.667526', NULL, 260, 71, 36, '63e9d2141f184941a34d7f85bc3ba175', '2026-10-11 09:07:56.667541', '2026-10-11 09:07:56.667543') ON CONFLICT (id) DO NOTHING;
INSERT INTO projects (owner_id, title, slug, short_description, problem_statement, objectives, features, tech_stack, prerequisites, difficulty, estimated_duration, expected_outcome, cover_image_url, screenshots, contributors, zip_storage_key, zip_file_size_bytes, github_url, live_demo_url, video_demo_url, domain, status, published_at, reviewer_notes, views_count, stars_count, bookmarks_count, id, created_at, updated_at) VALUES ('a47f8c3881724dd1a23795de9b726274', 'Zero-Trust Identity & API Gatekeeper', 'zero-trust-api-gateway', 'Reverse proxy micro-gateway enforcing mutual TLS, cryptographically signed JWT validation, and dynamic rate limiting.', 'Modern microservice architectures need perimeter security that verifies every request rather than trusting internal networks implicitly.', 'Implement high-performance reverse proxy routing in Go with token bucket rate limiting and Redis caching.', '["Distributed token bucket rate limiter", "mTLS upstream client verification", "Automated IP reputation and blocklist", "Structured audit log streaming"]', '["Go", "Docker", "Redis", "OAuth2", "Linux"]', 'Networking basics (TCP, TLS, HTTP/2), Go concurrency primitives.', 'Advanced', '3-4 weeks', 'A containerized reverse proxy protecting downstream services with sub-millisecond overhead.', NULL, '[]', '[]', NULL, 0, 'https://github.com/alexstudent/zero-trust-gateway', NULL, NULL, 'Cyber Security', 'Published', '2026-10-11 09:07:56.667547', NULL, 212, 61, 33, '894735e7862642bca5d83df1642d0694', '2026-10-11 09:07:56.667557', '2026-10-11 09:13:31.720790') ON CONFLICT (id) DO NOTHING;


