-- Table: preparation_materials
CREATE TABLE IF NOT EXISTS preparation_materials (
    id VARCHAR(36) PRIMARY KEY,
    role_id VARCHAR(36) NOT NULL REFERENCES preparation_roles(id) ON DELETE CASCADE,
    topic_id VARCHAR(36) REFERENCES preparation_topics(id) ON DELETE SET NULL,
    title VARCHAR(150) NOT NULL,
    description TEXT,
    file_path VARCHAR(500),
    file_name VARCHAR(255) NOT NULL,
    file_size_bytes INTEGER NOT NULL DEFAULT 0,
    page_count INTEGER NOT NULL DEFAULT 1,
    is_published BOOLEAN NOT NULL DEFAULT TRUE,
    download_count INTEGER NOT NULL DEFAULT 0,
    uploaded_by_id VARCHAR(36) REFERENCES users(id) ON DELETE SET NULL,
    created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);

